  "Our Italian-style coffeehouse and wine bar is the all-day town hall — morning latte to pre-dinner wine. Frequent happy hours bring cocktails, mocktails and complimentary snacks for friends and visitors.": "Nuestra cafetería y bar de vinos de estilo italiano es el punto de encuentro de todo el día — del latte de la mañana a la copa de vino antes de la cena. Los frecuentes happy hours ofrecen cócteles, bebidas sin alcohol y botanas de cortesía para amigos y visitas.",
  "Open photo: The Cypress Room": "Abrir foto: The Cypress Room",
