  "once-in-a-lifetime.": "lo irrepetible.",
  "Events & Adventures covers everything from everyday enjoyment to once-in-a-lifetime bucket list items — planned with residents, not just for them.": "Eventos y Aventuras abarca desde el disfrute de todos los días hasta esos sueños que solo se viven una vez — planeados con los residentes, no solo para ellos.",
  "Activity calendar": "Calendario de actividades",
  "The can-do spirit": "El espíritu de “sí se puede”",
  "If you can dream it,": "Si lo puede soñar,",
  "we’ll plan it.": "lo planeamos.",
  "Our residents have a can-do spirit that surprises everyone, including themselves —": "Nuestros residentes tienen un espíritu de “sí se puede” que sorprende a todos, incluso a ellos mismos —",
  "like grandmas in bikinis": "como abuelas en bikini",
  "running the charity car wash. Every Friday at the Activity Meeting, residents and our Events & Adventures Director go over next week’s calendar, pitch new ideas and settle the details over drinks and appetizers.": "atendiendo el lavado de autos con fines benéficos. Cada viernes, en la Reunión de Actividades, los residentes y nuestra Directora de Eventos y Aventuras revisan el calendario de la próxima semana, proponen nuevas ideas y afinan los detalles con bebidas y botanas.",
  "Events & Adventures Director": "Directora de Eventos y Aventuras",
  "Toni plans everything from Monday trivia to Gold Rush-era mine tours, and runs the Friday Activity Meeting where residents shape next week’s calendar.": "Toni planea de todo, desde la trivia de los lunes hasta visitas a minas de la Fiebre del Oro, y dirige la Reunión de Actividades de los viernes, donde los residentes dan forma al calendario de la próxima semana.",
