  "Please be in the Lobby ten minutes before departure. Seats are limited, so sign up online or at the front desk — if a trip is full, join the waitlist and we’ll call you if a seat opens.": "Por favor, esté en el Vestíbulo diez minutos antes de la salida. Los lugares son limitados, así que inscríbase en línea o en la recepción — si un paseo está completo, anótese en la lista de espera y le llamaremos si se libera un lugar.",
  "Help plan next week": "Ayude a planear la próxima semana",
  "Toni Glenn’s Activity Meeting is every Friday at {1} in The Rendezvous: next week’s events and changes, then drinks and appetizers before happy hour.": "La Reunión de Actividades de Toni Glenn es cada viernes a las {1} en The Rendezvous: los eventos y cambios de la próxima semana, y luego bebidas y botanas antes del happy hour.",
  "Families are always welcome": "Las familias siempre son bienvenidas",
  "Join a happy hour, a holiday party or a Sunday matinee with your loved one. Questions about an event? Call us at": "Acompañe a su ser querido a un happy hour, una fiesta de temporada o una matiné del domingo. ¿Preguntas sobre algún evento? Llámenos al",
  "See the Harbor Memory Care calendar": "Vea el calendario de Harbor (cuidado de la memoria)",
