  "Today’s classes, clubs, bus trips and happy hours at Prairie City Landing in Folsom, CA. Browse by day, week or month, filter by interest, sign up for trips online and print a large-print calendar.": "Las clases, clubes, paseos en autobús y happy hours de hoy en Prairie City Landing, en Folsom, CA. Consulte por día, semana o mes, filtre por interés, inscríbase a los paseos en línea e imprima un calendario en letra grande.",
  "Harbor’s private courtyard garden, with lawn and patio chairs": "El jardín privado del patio de Harbor, con césped y sillas de patio",
  "Residents playing hand drums together at Friday’s Drum Circle": "Residentes tocando tambores de mano en el Círculo de tambores de los viernes",
