  // ---------- /care-assessment ----------
  "What kind of support": "¿Qué tipo de apoyo",
  "fits": "le conviene",
  "A few friendly questions, about three minutes. We’ll suggest the living option that fits best, and why.": "Unas cuantas preguntas sencillas, en unos tres minutos. Le sugeriremos la opción de vivienda que mejor le conviene y por qué.",
  "Rather talk it through? Call": "¿Prefiere conversarlo? Llame a",
  "at": "al",
  "Question {1} of {2}": "Pregunta {1} de {2}",
  "Getting started": "Para empezar",
  "Who are you exploring for?": "¿Para quién está buscando?",
  "Myself": "Para mí",
  "My mother": "Mi madre",
  "My father": "Mi padre",
  "My spouse or partner": "Mi cónyuge o pareja",
  "Someone else I care about": "Otra persona que me importa",
  "Back": "Atrás",
  "Next": "Siguiente",
  "Ten friendly questions to see whether Independent Living, Assisted Living Services or Harbor Memory Care is the right fit.": "Diez preguntas sencillas para saber si Vida Independiente, Servicios de Vida Asistida o Harbor (cuidado de la memoria) es la mejor opción.",
  "Their first name (optional)": "Su nombre de pila (opcional)",
  "your mother": "su madre",
  "your father": "su padre",
  "your partner": "su pareja",
  "your loved one": "su ser querido",
  "Where is {name} living right now?": "¿Dónde vive {name} actualmente?",
  "How are medications going for {name}?": "¿Cómo le va a {name} con sus medicamentos?",
  "What about bathing and getting dressed, for {name}?": "¿Y cómo le va a {name} al bañarse y vestirse?",
  "And meals? Which sounds most like {name}?": "¿Y las comidas? ¿Qué describe mejor a {name}?",
  "How does {name} get around?": "¿Cómo se desplaza {name}?",
  "Have there been changes in memory for {name}?": "¿Ha notado cambios en la memoria de {name}?",
  "What are nights like for {name}?": "¿Cómo son las noches de {name}?",
  "How’s {name}’s social life these days?": "¿Cómo está la vida social de {name} estos días?",
  "What would {name} love to have more of?": "¿De qué le gustaría disfrutar más a {name}?",
  "Our suggestion for {name}": "Nuestra sugerencia para {name}",
  "could make every day easier": "podrían hacer cada día más fácil",
  "may be the right place": "puede ser el lugar indicado",
  "{Name} sounds independent and ready to enjoy more of life, with none of the chores. Independent Living means a real apartment home, three restaurants, a calendar full of things to do, and our team on site {1} hours, just in case.": "{Name} parece independiente y con ganas de disfrutar más de la vida, sin quehaceres. Vida Independiente significa un verdadero departamento, tres restaurantes, un calendario lleno de actividades y nuestro equipo presente las {1} horas, por si acaso.",
  "You’d have your own apartment and your own routine, with a Care Partner close by for the parts of the day that have become harder. Assisted Living Services are delivered discreetly in every apartment, so nobody ever has to move to get more help.": "Tendría su propio departamento y su propia rutina, con una asistente de cuidado cerca para los momentos del día que se han vuelto más difíciles. Los Servicios de Vida Asistida se ofrecen discretamente en todos los departamentos, para que nadie tenga que mudarse para recibir más ayuda.",
  "You’d have your own apartment and your own routine, with a Care Partner close by for the parts of the day that have become harder, from medications to bathing. Assisted Living Services are delivered discreetly in every apartment, so nobody ever has to move to get more help.": "Tendría su propio departamento y su propia rutina, con una asistente de cuidado cerca para los momentos del día que se han vuelto más difíciles, desde los medicamentos hasta el baño. Los Servicios de Vida Asistida se ofrecen discretamente en todos los departamentos, para que nadie tenga que mudarse para recibir más ayuda.",
  "{Name} would have an apartment and a routine of their own, with a Care Partner close by for the parts of the day that have become harder. Assisted Living Services are delivered discreetly in every apartment, so nobody ever has to move to get more help.": "{Name} tendría su propio departamento y su propia rutina, con una asistente de cuidado cerca para los momentos del día que se han vuelto más difíciles. Los Servicios de Vida Asistida se ofrecen discretamente en todos los departamentos, para que nadie tenga que mudarse para recibir más ayuda.",
  "{Name} would have an apartment and a routine of their own, with a Care Partner close by for the parts of the day that have become harder, from medications to bathing. Assisted Living Services are delivered discreetly in every apartment, so nobody ever has to move to get more help.": "{Name} tendría su propio departamento y su propia rutina, con una asistente de cuidado cerca para los momentos del día que se han vuelto más difíciles, desde los medicamentos hasta el baño. Los Servicios de Vida Asistida se ofrecen discretamente en todos los departamentos, para que nadie tenga que mudarse para recibir más ayuda.",
  "You’d live in Harbor, our secured, home-like memory care neighborhood with its own courtyard and its own team. Harbor is built around what residents can still do and love: weekly outings, music, gardening and purposeful roles in everyday life.": "Viviría en Harbor, nuestra área de cuidado de la memoria, segura y hogareña, con su propio patio y su propio equipo. Harbor gira en torno a lo que los residentes todavía pueden hacer y disfrutan: salidas semanales, música, jardinería y roles con propósito en la vida diaria.",
  "You’d live in Harbor, our secured, home-like memory care neighborhood with its own courtyard and its own team. Harbor is built around what residents can still do and love, and families tell us the peace of mind comes quickly: weekly outings, music, gardening and purposeful roles in everyday life.": "Viviría en Harbor, nuestra área de cuidado de la memoria, segura y hogareña, con su propio patio y su propio equipo. Harbor gira en torno a lo que los residentes todavía pueden hacer y disfrutan, y las familias nos dicen que la tranquilidad llega pronto: salidas semanales, música, jardinería y roles con propósito en la vida diaria.",
  "{Name} would live in Harbor, our secured, home-like memory care neighborhood with its own courtyard and its own team. Harbor is built around what residents can still do and love: weekly outings, music, gardening and purposeful roles in everyday life.": "{Name} viviría en Harbor, nuestra área de cuidado de la memoria, segura y hogareña, con su propio patio y su propio equipo. Harbor gira en torno a lo que los residentes todavía pueden hacer y disfrutan: salidas semanales, música, jardinería y roles con propósito en la vida diaria.",
  "{Name} would live in Harbor, our secured, home-like memory care neighborhood with its own courtyard and its own team. Harbor is built around what residents can still do and love, and families tell us the peace of mind comes quickly: weekly outings, music, gardening and purposeful roles in everyday life.": "{Name} viviría en Harbor, nuestra área de cuidado de la memoria, segura y hogareña, con su propio patio y su propio equipo. Harbor gira en torno a lo que los residentes todavía pueden hacer y disfrutan, y las familias nos dicen que la tranquilidad llega pronto: salidas semanales, música, jardinería y roles con propósito en la vida diaria.",
