  "Address, directions, phone numbers, visiting hours and a department directory for Prairie City Landing, 645 Willard Drive, Folsom, CA 95630.": "Dirección, cómo llegar, teléfonos, horarios de visita y un directorio de departamentos de Prairie City Landing, 645 Willard Drive, Folsom, CA 95630.",
