  "text": "mensaje de texto",
  "Find us in": "Encuéntrenos en",
  "Just off US-50 next to Folsom High School, minutes from historic downtown Folsom. Visitors are always welcome.": "Justo al lado de la US-50, junto a Folsom High School, a minutos del centro histórico de Folsom. Los visitantes siempre son bienvenidos.",
