  "About {1} minutes from Sacramento International Airport (SMF)": "A unos {1} minutos del Aeropuerto Internacional de Sacramento (SMF)",
  "From Sacramento (US-50 East)": "Desde Sacramento (US-50 Este)",
  "Take US-50 East toward Folsom. Exit at Prairie City Road, turn left and continue north. Turn right on Iron Point Road, then left on Willard Drive. We are on your right, next to Folsom High School.": "Tome la US-50 Este hacia Folsom. Salga en Prairie City Road, dé vuelta a la izquierda y siga hacia el norte. Dé vuelta a la derecha en Iron Point Road y luego a la izquierda en Willard Drive. Estamos a su derecha, junto a Folsom High School.",
  "From Sacramento International Airport": "Desde el Aeropuerto Internacional de Sacramento",
