  "Meet the leadership and department directors at Prairie City Landing, our Team Steward of the Month, instructors and Resident Council president.": "Conozca a la dirección y a los directores de departamento de Prairie City Landing, a nuestro Team Steward of the Month, a los instructores y al presidente del Consejo de Residentes.",
