  "home": "hogar",
  "Every director at Prairie City Landing works on site, knows residents by name and picks up the phone. Here’s who they are, and who to call about what.": "Cada director de Prairie City Landing trabaja aquí mismo, conoce a los residentes por su nombre y contesta el teléfono. Estas son las personas y a quién llamar para cada cosa.",
  "Your": "Sus",
  "first": "primeras",
  "calls": "llamadas",
  "Cheryl leads the community and received the California Assisted Living Association’s Outstanding Executive Director Award. Her door is open, and she hosts a monthly Town Hall with residents.": "Cheryl dirige la comunidad y recibió el premio a la Directora Ejecutiva Destacada de la California Assisted Living Association. Su puerta siempre está abierta, y cada mes organiza una reunión comunitaria con los residentes.",
  "Call about:": "Llame para:",
  "Anything else — or a concern": "Cualquier otro asunto, o alguna inquietud",
  "Cynthia is your first call. She leads every tour, answers every question about apartments and pricing, and helps families plan a move at their own pace.": "Cynthia es su primera llamada. Dirige cada visita, responde todas las preguntas sobre departamentos y precios, y ayuda a las familias a planear la mudanza a su propio ritmo.",
  "Tours, apartments, pricing and move-ins": "Visitas, departamentos, precios y mudanzas",
  "Jan leads the Care Partner team, completes pre-move-in assessments and builds each resident’s care plan with families and healthcare providers.": "Jan dirige el equipo de asistentes de cuidado, realiza las evaluaciones previas a la mudanza y elabora el plan de cuidado de cada residente junto con las familias y los proveedores de salud.",
  "Care plans, assessments and medications": "Planes de cuidado, evaluaciones y medicamentos",
