  "who take care": "cuidan",
  "Full-time team members are eligible for the full benefits package. Ask our recruiter about part-time eligibility.": "Los miembros del equipo de tiempo completo tienen derecho al paquete completo de prestaciones. Pregunte a nuestro equipo de reclutamiento sobre los requisitos para medio tiempo.",
  "Medical, dental and vision insurance": "Seguro médico, dental y de la vista",
