  "Recruiter phone screen": "Entrevista telefónica con reclutamiento",
  "A short call with our recruiter to talk about the role, your schedule and your questions.": "Una llamada breve con nuestro equipo de reclutamiento para hablar del puesto, su horario y sus preguntas.",
  "Community interview": "Entrevista en la comunidad",
  "Meet the department director at Prairie City Landing and see the community for yourself.": "Conozca al director del departamento en Prairie City Landing y vea la comunidad en persona.",
