  "A kitchen with light wood cabinets, stainless appliances, a solid-surface island and pendant lights": "Una cocina con gabinetes de madera clara, electrodomésticos de acero inoxidable, isla de superficie sólida y lámparas colgantes",
  "A bright bathroom with a walk-in shower, grab bar and solid-surface vanity": "Un baño luminoso con regadera sin escalón, barra de apoyo y lavabo de superficie sólida",
  "Looking in from the entry: a round dining table, a dresser and the bedroom through a wide doorway": "Vista desde la entrada: una mesa de comedor redonda, una cómoda y la recámara tras una puerta amplia",
  "A bedroom with a queen bed, two lamps, a ceiling fan and a large window": "Una recámara con cama queen, dos lámparas, ventilador de techo y una ventana grande",
  "The courtyard seen from the balconies: lawn, palms and outdoor seating": "El patio visto desde los balcones: césped, palmeras y asientos al aire libre",
  "Morning coffee on your own balcony, looking over the courtyard.": "El café de la mañana en su propio balcón, con vista al patio.",
  "Courtyard views": "Vistas al patio",
  "Balconies look over the courtyard’s palms, lawn and gardens.": "Los balcones dan a las palmeras, el césped y los jardines del patio.",
  "Fire table, barbecues and outdoor dining, just downstairs.": "Mesa con fogata, asadores y comedor al aire libre, justo abajo.",
  "A second bedroom with a blue accent wall, queen bed and upholstered bench": "Una segunda recámara con una pared de acento azul, cama queen y banca tapizada",
  "The courtyard from above: paths, planters, the fire table and outdoor dining": "El patio desde arriba: senderos, jardineras, la mesa con fogata y el comedor al aire libre",
  "A kitchen of your own for breakfast and snacks, with three restaurants downstairs for everything else.": "Una cocina propia para el desayuno y los antojitos, con tres restaurantes abajo para todo lo demás.",
  "Grab bars by the toilet and in the shower, installed from day one.": "Barras de apoyo junto al inodoro y en la regadera, instaladas desde el primer día.",
  "Harbor’s living room with armchairs and a fireplace, just outside the residents’ rooms": "La sala de Harbor con sillones y chimenea, justo afuera de las habitaciones de los residentes",
  "A furnished private room with a queen bed, blue accent wall and a large window": "Una habitación privada amueblada con cama queen, pared de acento azul y una ventana grande",
  "A bright bathroom with a walk-in shower, grab bars and a solid-surface vanity": "Un baño luminoso con regadera sin escalón, barras de apoyo y lavabo de superficie sólida",
  "Harbor’s secured courtyard with lawn, garden chairs and a shade tree": "El patio protegido de Harbor con césped, sillas de jardín y un árbol que da sombra",
  "A bathroom shared with one neighbour, with a walk-in shower and grab bars.": "Un baño compartido con un vecino, con regadera sin escalón y barras de apoyo.",

