  "You sound independent and ready to enjoy more of life, with none of the chores. Independent Living means a real apartment home, three restaurants, a calendar full of things to do, and our team on site {1} hours, just in case.": "Usted parece independiente y con ganas de disfrutar más de la vida, sin quehaceres. Vida Independiente significa un verdadero departamento, tres restaurantes, un calendario lleno de actividades y nuestro equipo presente las {1} horas, por si acaso.",
  "Call Cynthia": "Llamar a Cynthia",
