  "What Independent Living includes": "Qué incluye Vida Independiente",
  "Things you’ll love": "Lo que le encantará",
  "More than {1} fitness classes a week with Jason Cherry, our full-time Fitness Director": "Más de {1} clases de acondicionamiento físico a la semana con Jason Cherry, nuestro Director de Acondicionamiento Físico de tiempo completo",
  "Events & Adventures outings every week, from wineries to Gold Rush-era mine tours": "Salidas de Eventos y Aventuras cada semana, desde viñedos hasta recorridos por minas de la Fiebre del Oro",
  "Three restaurants downstairs: The Cypress Room, Natoma Café and The Rendezvous": "Tres restaurantes en la planta baja: The Cypress Room, Natoma Café y The Rendezvous",
  "Art Studio classes with visiting artists, plus live music on the calendar every week": "Clases en el Taller de arte con artistas invitados, además de música en vivo en el calendario cada semana",
  "Raised planters and a cutting garden in the courtyard": "Jardineras elevadas y un jardín de flores para cortar en el patio",
  "Dogs and cats welcome, with their own outdoor area in the courtyard": "Perros y gatos son bienvenidos, con su propia área al aire libre en el patio",
  "Religious services in the Theatre, and faith gatherings on the calendar": "Servicios religiosos en el Teatro y reuniones de fe en el calendario",
