  // ---------- Tenfold parent site and Bruceville Point ----------
  "Tenfold Senior Living · Different By Design": "Tenfold Senior Living · Diferente por diseño",
  "Luxury senior living communities in Folsom and Elk Grove, California: Independent Living, Assisted Living Services and Harbor Memory Care.": "Comunidades de lujo para personas mayores en Folsom y Elk Grove, California: Vida Independiente, Servicios de Vida Asistida y Harbor (cuidado de la memoria).",
  "that page.": "esa página.",
  "It may have moved, or the address may be mistyped. These will take you somewhere good:": "Es posible que se haya movido o que la dirección esté mal escrita. Estos enlaces le llevarán a un buen lugar:",
  "Tenfold home": "Inicio de Tenfold",
  "A quiet moment — coffee at The Rendezvous, a book in the Living Room, or a stroll in the courtyard.": "Un momento de calma: un café en The Rendezvous, un libro en la sala de estar o un paseo por el patio.",
  "Tenfold Senior Living home": "Inicio de Tenfold Senior Living",
  "Equal Housing Opportunity": "Igualdad de Oportunidades en la Vivienda",
  "· about $12,000 a year saved": "· un ahorro de unos $12,000 al año",
  "Sacramento County’s newest luxury senior living community.": "La comunidad de lujo para personas mayores más nueva del condado de Sacramento.",
  "A sunny courtyard with palms, lawn and outdoor seating": "Un patio soleado con palmeras, césped y asientos al aire libre",
  "life you love.": "estilo de vida que le encanta.",
  "Paint and Sip": "Pintar y brindar",
  "Park outings": "Paseos al parque",
  "Today at Bruceville Point": "Hoy en Bruceville Point",
  "Good morning from Elk Grove. Here’s what’s happening around the community.": "Buenos días desde Elk Grove. Esto es lo que está pasando en la comunidad.",
  "Corn & Potato Chowder": "Crema de elote y papa",
  "Seared Scallops": "Callos de hacha sellados",
  "Fish Tacos": "Tacos de pescado",
  "Grilled cod, cabbage slaw, chipotle crema, corn tortillas": "Bacalao a la parrilla, ensalada de col, crema de chipotle, tortillas de maíz",
  "A bright apartment living room and kitchen": "La sala y la cocina de un departamento luminoso",
  "Roomy, light-filled studio, one- and two-bedroom apartments up to 1,184 square feet, with full kitchens, your own washer and dryer, and room for full-sized furniture.": "Amplios y luminosos departamentos tipo estudio, de una y de dos recámaras de hasta 1,184 pies², con cocinas completas, su propia lavadora y secadora, y espacio para muebles de tamaño normal.",
  "A full range of Assisted Living Services, delivered privately in your own apartment, so you can stay in your home as your needs change.": "Una gama completa de Servicios de Vida Asistida, prestados en privado en su propio departamento, para que pueda quedarse en su hogar a medida que cambien sus necesidades.",
  "Harbor’s bright living room with armchairs": "La luminosa sala de estar de Harbor, con sillones",
  "An environment of youthful optimism, where ‘we can’t’ becomes ‘how can we…?’ for every resident.": "Un ambiente de optimismo juvenil, donde el “no podemos” se convierte en “¿cómo podemos…?” para cada residente.",
  "Four words shape every class, menu, outing and conversation at Bruceville Point: Youthful, Useful, Spontaneous and Mobile.": "Cuatro palabras dan forma a cada clase, menú, salida y conversación en Bruceville Point: Youthful (juvenil), Useful (útil), Spontaneous (espontáneo) y Mobile (activo).",
  "Every menu is designed by Culinary Director Eric Auclair. Eat when you like, where you like, with whoever you like.": "Cada menú es creado por nuestro Director Culinario, Eric Auclair. Coma cuando quiera, donde quiera y con quien quiera.",
  "A dining room set with white tablecloths": "Un comedor con manteles blancos",
  "A seasonally inspired weekly menu of local, market-fresh ingredients — and dessert.": "Un menú semanal inspirado en la temporada, con ingredientes locales y frescos del mercado, y postre.",
  "Residents gathered at outdoor tables under orange umbrellas and palms": "Residentes reunidos en mesas al aire libre bajo sombrillas naranjas y palmeras",
  "All-day California-casual": "Cocina informal californiana todo el día",
  "Modern comfort food all day: soups, salads, sandwiches, pasta and a daily chef’s special.": "Comida casera moderna todo el día: sopas, ensaladas, sándwiches, pasta y una especialidad diaria del chef.",
  "Morning coffee to happy hour — the community’s ‘town hall’.": "Del café de la mañana al happy hour: el punto de encuentro de la comunidad.",
  "Residents enjoying a game together": "Residentes disfrutando juntos de un juego",
  "Engage, Connect, Celebrate Every Day": "Participar, convivir y celebrar todos los días",
  "A high school visitor joins the Events & Adventures team for Bingo in the Bistro — and leads an axe-throwing class.": "Una visitante de preparatoria se une al equipo de Eventos y Aventuras para el Bingo en The Bistro, y dirige una clase de lanzamiento de hachas.",
  "I moved here to thrive": "Me mudé aquí para vivir plenamente",
  "Meet Linda, the star of our Day in the Life video, and the friendships that turned a quiet house into a lively life.": "Conozca a Linda, la protagonista de nuestro video Un día en la vida, y las amistades que convirtieron una casa silenciosa en una vida llena de actividad.",
  "Three men talking outdoors": "Tres hombres conversando al aire libre",
  "Finding Camaraderie and Care": "Encontrar compañerismo y cuidado",
  "Bob, Bill and Lou — veterans and caregivers — on the friendships that eased the loneliness of caring for a loved one.": "Bob, Bill y Lou, veteranos y cuidadores, hablan de las amistades que aliviaron la soledad de cuidar a un ser querido.",
  "Emergency response system in every apartment, with our team on site 24 hours": "Sistema de respuesta a emergencias en cada departamento, con nuestro equipo en el lugar las 24 horas",
  "Secure gated access with coded entry and all-hours camera surveillance": "Acceso seguro con portón, entrada con código y vigilancia con cámaras a toda hora",
  "Covered parking available": "Estacionamiento techado disponible",
  "All maintenance, with handyman services as needed": "Todo el mantenimiento, con servicios de reparaciones según se necesiten",
  "Assisted Living Services available in your own apartment": "Servicios de Vida Asistida disponibles en su propio departamento",
  "I liked knowing that when I moved to Bruceville Point, if I needed more help in the future, I could get it.": "Me gustó saber que, al mudarme a Bruceville Point, si en el futuro necesitaba más ayuda, podría recibirla.",
  "Resident": "Residente",
  "I moved here to thrive instead of just survive.": "Me mudé aquí para vivir plenamente, no solo para sobrevivir.",
  "I love all the classes because they offer a variety of ways to help us stay fit.": "Me encantan todas las clases porque ofrecen muchas maneras de ayudarnos a mantenernos en forma.",
  "Bruceville Point · Luxury Senior Living in Elk Grove, CA": "Bruceville Point · Comunidad de lujo para personas mayores en Elk Grove, CA",
  "Sacramento County’s newest luxury senior living community in Elk Grove, CA. Independent Living from $5,100 a month, Assisted Living Services and Harbor Memory Care. Different By Design.": "La comunidad de lujo para personas mayores más nueva del condado de Sacramento, en Elk Grove, CA. Vida Independiente desde $5,100 al mes, Servicios de Vida Asistida y Harbor (cuidado de la memoria). Diferente por diseño.",
  "Visit Bruceville Point": "Visite Bruceville Point",
  "Tour the apartments, meet the team and see the three restaurants for yourself.": "Recorra los departamentos, conozca al equipo y vea en persona los tres restaurantes.",
  "Tours by appointment · call (916) 226-5300": "Visitas con cita previa · llame al (916) 226-5300",
