  "Bruceville Point home": "Inicio de Bruceville Point",
  "A quiet moment — coffee at The Bistro, a book in the Lobby, or a stroll along the walking paths.": "Un momento de calma: un café en The Bistro, un libro en el Vestíbulo o un paseo por los senderos.",
