  "funding care, senior living 101 and the family decision toolkit. Download any of them, free.": "cómo pagar el cuidado, Senior Living 101 y el kit de decisiones para familias. Descargue cualquiera de ellas, gratis.",
  "Compare what staying at home really costs each month with life at Bruceville Point, from $5,100 a month with no second-person fee.": "Compare lo que realmente cuesta cada mes quedarse en casa con la vida en Bruceville Point, desde $5,100 al mes y sin cargo por segunda persona.",
  "A house has a lot of bills hiding in it. Add yours up, line by line, and see how they compare with one monthly rent at Bruceville Point.": "Una casa esconde muchas cuentas. Sume las suyas, renglón por renglón, y vea cómo se comparan con una sola renta mensual en Bruceville Point.",
  "Monthly figures. We’ve filled in typical Elk Grove-area amounts; change any of them to match yours.": "Cifras mensuales. Hemos anotado montos típicos de la zona de Elk Grove; cambie cualquiera para que coincida con los suyos.",
  "At Bruceville Point": "En Bruceville Point",
  "· about $10,000 a year saved": "· un ahorro de unos $10,000 al año",
  "Three restaurants on site": "Tres restaurantes en la comunidad",
  "Outings with our drivers, departing from the Lobby": "Salidas con nuestros choferes, desde el Vestíbulo",
  "25+ fitness classes a week on site": "Más de 25 clases de ejercicio por semana en la comunidad",
  "Events & Adventures on the calendar": "Eventos y Aventuras en el calendario",
  "Total at Bruceville Point": "Total en Bruceville Point",
  "Bruceville Point could cost": "Bruceville Point podría costar",
  "Your costs at home: $6,040 a month. At Bruceville Point: $5,550 a month.": "Sus costos en casa: $6,040 al mes. En Bruceville Point: $5,550 al mes.",
  "less at Bruceville Point": "menos en Bruceville Point",
  "Figures are estimates for planning. Rents shown are starting prices; Jaime Cervantes can give you exact pricing for the apartments open now at": "Las cifras son estimaciones para planificar. Las rentas que se muestran son precios iniciales; Jaime Cervantes puede darle los precios exactos de los departamentos disponibles ahora al",
  "Youthful isn’t about age. It’s the feeling of learning something new, laughing until your sides hurt and trying the thing you always meant to. Visiting instructors teach in the Art Studio, the monthly Paint and Sip brings residents, families and Care Partners together at the easel, and happy hour in the Bistro has live music.": "Youthful (juvenil) no tiene que ver con la edad. Es la sensación de aprender algo nuevo, reír hasta que duela el estómago y probar eso que siempre quiso hacer. Instructores invitados dan clases en el Taller de arte, el Pintar y brindar mensual reúne a residentes, familias y asistentes de cuidado frente al caballete, y el happy hour en The Bistro tiene música en vivo.",
  "Everyone has something to give. Residents lead clubs, plant the courtyard’s raised beds and serve on the Resident Council. At the Friday Activity Meeting, residents shape next week’s calendar with our Events & Adventures Director.": "Todos tenemos algo que aportar. Los residentes dirigen clubes, siembran las jardineras elevadas del patio y forman parte del Consejo de Residentes. En la Reunión de Actividades de los viernes, los residentes planean el calendario de la semana siguiente con nuestro Director de Eventos y Aventuras.",
  "Say yes to the unexpected. Join the bus to the Aerospace Museum of California, a sunny afternoon in a local park or a last-minute lunch out — or skip it all for a quiet afternoon. Your day, your decisions.": "Dígale que sí a lo inesperado. Súbase al autobús rumbo al Aerospace Museum of California, a una tarde soleada en un parque de la zona o a un almuerzo fuera de último momento, o sáltese todo y disfrute una tarde tranquila. Su día, sus decisiones.",
  "Fitness keeps you from ‘stepping back’ from life. Our full-time Fitness Director teaches more than 25 classes a week — from Step Aerobics and Better Balance to strength training, bocce and disc golf.": "El ejercicio le ayuda a no “dar un paso atrás” en la vida. Nuestra Directora de Acondicionamiento Físico de tiempo completo imparte más de 25 clases por semana, desde Step Aerobics y Mejor equilibrio hasta entrenamiento de fuerza, bocce y disc golf.",
  "More than 25 classes a week with Tina Trillo.": "Más de 25 clases por semana con Tina Trillo.",
  "Life at Bruceville Point is YUSM — Youthful, Useful, Spontaneous and Mobile. Explore the activity calendar, dining, fitness, Events & Adventures and our amazing spaces.": "La vida en Bruceville Point es YUSM: Youthful (juvenil), Useful (útil), Spontaneous (espontáneo) y Mobile (activo). Explore el calendario de actividades, la gastronomía, el acondicionamiento físico, Eventos y Aventuras y nuestros espacios increíbles.",
  "Today’s classes, clubs, bus trips and happy hours at Bruceville Point in Elk Grove, CA. Browse by day, week or month, filter by interest, sign up for trips online and print a large-print calendar.": "Las clases, clubes, paseos en autobús y happy hours de hoy en Bruceville Point, en Elk Grove, CA. Consulte por día, semana o mes, filtre por interés, inscríbase en paseos en línea e imprima un calendario en letra grande.",
  "Gym": "Gimnasio",
  "Timothy Smith’s Activity Meeting is every Friday at 2:45 pm in The Bistro: next week’s events and changes, then drinks and appetizers before happy hour.": "La Reunión de Actividades de Timothy Smith es cada viernes a las 2:45 pm en The Bistro: los eventos y cambios de la próxima semana, y luego bebidas y botanas antes del happy hour.",
  "Sit and Stretch": "Estiramiento sentado",
  "Morning Trivia": "Trivia matutina",
  "Mindfulness Moment": "Momento de atención plena",
