  "Brain Games": "Juegos de ingenio",
  "Harbor keeps its own activity calendar, 12 hours a day — ceramics, music, pet therapy, storytelling, gardening and a weekly outing — and Harbor residents are invited to every community event too.": "Harbor tiene su propio calendario de actividades, 12 horas al día: cerámica, música, terapia con mascotas, narración de historias, jardinería y una salida semanal; y los residentes de Harbor también están invitados a todos los eventos de la comunidad.",
  "A cocktail on the bar at The Bistro": "Un cóctel en la barra de The Bistro",
  "Happy hour every day in The Bistro, with live music on Tuesdays and Fridays, 3:00–4:00 pm. Cocktails, mocktails, wine by the glass and complimentary snacks for friends and visitors — bring the family.": "Happy hour todos los días en The Bistro, con música en vivo los martes y viernes, de 3:00 a 4:00 pm. Cócteles, bebidas sin alcohol, vino por copa y botanas de cortesía para amigos y visitas: traiga a la familia.",
  "Acoustic Guitar": "Guitarra acústica",
  "Jazz Trio": "Trío de jazz",
  "Country Classics": "Clásicos country",
  "Our menus are written in our own kitchen — and each month our Dining Experience Director gives residents a cooking lesson.": "Nuestros menús se escriben en nuestra propia cocina, y cada mes nuestra Directora de Experiencia Gastronómica da a los residentes una clase de cocina.",
  "Eric designs the menus for the Cypress Room, Stone Lakes Cafe and the Bistro.": "Eric diseña los menús de The Cypress Room, Stone Lakes Cafe y The Bistro.",
  "Danyale runs all three restaurants, takes lunch and private dining reservations, and gives residents a cooking lesson each month.": "Danyale dirige los tres restaurantes, toma las reservaciones para el almuerzo y para comidas privadas, y da a los residentes una clase de cocina cada mes.",
  "A latte with foam art": "Un latte con arte en la espuma",
  "The best way to get to know Bruceville Point is over a meal. Visiting a loved one, or thinking about a move? Book a table in The Cypress Room or Stone Lakes Cafe and we’ll take care of the rest.": "La mejor manera de conocer Bruceville Point es durante una comida. ¿Viene a ver a un ser querido o está pensando en mudarse? Reserve una mesa en The Cypress Room o Stone Lakes Cafe y nosotros nos encargamos del resto.",
  "Today’s menus at The Cypress Room, Stone Lakes Cafe and The Bistro at Bruceville Point in Elk Grove, CA — chef’s specials, soup of the day, gluten-free, vegetarian and dairy-free choices, a daily happy hour, and lunch reservations for families and guests.": "Los menús de hoy en The Cypress Room, Stone Lakes Cafe y The Bistro de Bruceville Point, en Elk Grove, CA: especialidades del chef, sopa del día, opciones sin gluten, vegetarianas y sin lácteos, un happy hour diario y reservaciones de almuerzo para familias e invitados.",
  "White-tablecloth dining in The Cypress Room, California-casual comfort food all day at Stone Lakes Cafe, and espresso, panini and a daily happy hour in The Bistro. Every menu is designed here, by our own culinary team.": "Comedor con mantel blanco en The Cypress Room, comida casera informal californiana todo el día en Stone Lakes Cafe, y espresso, panini y un happy hour diario en The Bistro. Cada menú se crea aquí, por nuestro propio equipo culinario.",
  "Residents sharing a meal at a white-tablecloth table": "Residentes compartiendo una comida en una mesa con mantel blanco",
  "Avocado toast with a poached egg": "Pan tostado con aguacate y huevo pochado",
