  "Prosciutto & Fig Panini": "Panini de prosciutto e higo",
  "Prosciutto, fig jam, fontina, arugula": "Prosciutto, mermelada de higo, fontina, arúgula",
  "like the resident who toured the Aerospace Museum": "como el residente que recorrió el Aerospace Museum",
  "and found planes he once flew. Every Friday at the Activity Meeting, residents and our Events & Adventures Director go over next week’s calendar, pitch new ideas and settle the details over drinks and appetizers.": "y encontró aviones que alguna vez piloteó. Cada viernes, en la Reunión de Actividades, los residentes y nuestro Director de Eventos y Aventuras revisan el calendario de la próxima semana, proponen nuevas ideas y afinan los detalles con bebidas y botanas.",
  "Timothy leads the Events & Adventures team and the calendar of classes, clubs, outings and celebrations.": "Timothy dirige el equipo de Eventos y Aventuras y el calendario de clases, clubes, salidas y celebraciones.",
  "All trips leave from the Lobby. Seats are limited — sign up at the front desk or with Timothy.": "Todos los paseos salen del Vestíbulo. Los lugares son limitados: inscríbase en la recepción o con Timothy.",
  "Dinner Trip: Old Town Elk Grove": "Salida a cenar: Old Town Elk Grove",
