  "Fast Food Friday: Burgers in Laguna": "Viernes de comida rápida: hamburguesas en Laguna",
  "Bus Trip: Old Sacramento & California State Railroad Museum": "Paseo en autobús: Old Sacramento y California State Railroad Museum",
  "From everyday enjoyment to once-in-a-lifetime bucket list items: trips, outings, parties and adventures at Bruceville Point in Elk Grove, CA.": "Del disfrute de todos los días a esos sueños que se cumplen una vez en la vida: paseos, salidas, fiestas y aventuras en Bruceville Point, en Elk Grove, CA.",
