  "Tina is our full-time, in-house Fitness Director. She leads more than 25 classes a week, active outings and talks on nutrition and mindfulness.": "Tina es nuestra Directora de Acondicionamiento Físico de tiempo completo en la comunidad. Imparte más de 25 clases por semana, salidas activas y pláticas sobre nutrición y atención plena.",
  "Strength training and resistance bands": "Entrenamiento de fuerza y bandas de resistencia",
  "Sit and stretch": "Estiramiento sentado",
  "Outings to local trails, parks and recreation areas": "Salidas a senderos, parques y áreas recreativas de la zona",
  "Disc golf, basketball and Olympic rings": "Disc golf, básquetbol y anillos olímpicos",
  "Bocce tournaments on the courtyard court": "Torneos de bocce en la cancha del patio",
  "Talks on nutrition and mindfulness in the Theatre": "Pláticas sobre nutrición y atención plena en el Teatro",
  "Gardening in the courtyard’s raised beds": "Jardinería en las jardineras elevadas del patio",
  "Community walking paths": "Senderos para caminar de la comunidad",
  "when you visit.": "durante su visita.",
  "More than 25 fitness classes a week at Bruceville Point, led by full-time Fitness Director Tina Trillo: Step Aerobics, strength training, sit and stretch, bocce, disc golf, axe throwing and outings to local trails and parks.": "Más de 25 clases de ejercicio por semana en Bruceville Point, dirigidas por la Directora de Acondicionamiento Físico de tiempo completo Tina Trillo: Step Aerobics, entrenamiento de fuerza, estiramiento sentado, bocce, disc golf, lanzamiento de hachas y salidas a senderos y parques de la zona.",
  "Bocce Tournament: Round One": "Torneo de bocce: primera ronda",
  "Join Tina for a class when you visit, then stay for lunch in one of our three restaurants.": "Tome una clase con Tina durante su visita y luego quédese a almorzar en uno de nuestros tres restaurantes.",
  "More than 25 indoor classes a week with our full-time, in-house Fitness Director, plus a personal trainer and active outings that build strength, endurance, flexibility and balance.": "Más de 25 clases bajo techo por semana con nuestra Directora de Acondicionamiento Físico de tiempo completo, además de un entrenador personal y salidas activas que fortalecen la fuerza, la resistencia, la flexibilidad y el equilibrio.",
  "Open photo: The Gym": "Abrir foto: El gimnasio",
  "A gym with exercise machines": "Un gimnasio con aparatos de ejercicio",
  "The Gym": "El gimnasio",
  "Open photo: Group exercise": "Abrir foto: Ejercicio en grupo",
  "A class floor set up with chairs": "Un salón de clases con sillas acomodadas",
  "Group exercise": "Ejercicio en grupo",
  "Open photo: Outings to local trails and parks": "Abrir foto: Salidas a senderos y parques de la zona",
  "Outings to local trails and parks": "Salidas a senderos y parques de la zona",
