  "Weekdays — call the main line": "Entre semana: llame a la línea principal",
  "and ask the front desk to put you through.": "y pida a la recepción que le comunique.",
  "Call the front desk and ask for Marianne Richardson": "Llame a la recepción y pregunte por Marianne Richardson",
