  "Address, directions, phone numbers, visiting information and who to ask for at Bruceville Point, 9730 Backer Ranch Road, Elk Grove, CA 95757.": "Dirección, indicaciones, números de teléfono, información para visitas y a quién preguntar en Bruceville Point, 9730 Backer Ranch Road, Elk Grove, CA 95757.",
  "Just off Bruceville Road, a few blocks south of Elk Grove Boulevard, minutes from Old Town Elk Grove. Visitors are always welcome.": "Junto a Bruceville Road, a pocas cuadras al sur de Elk Grove Boulevard y a minutos de Old Town Elk Grove. Las visitas siempre son bienvenidas.",
  "The front entrance of the community": "La entrada principal de la comunidad",
  "By checking this box, I agree to receive recurring automated text messages from Bruceville Point at the mobile number provided, about": "Al marcar esta casilla, acepto recibir mensajes de texto automáticos y recurrentes de Bruceville Point en el número de celular proporcionado, sobre",
  "Book an in-person or video tour of Bruceville Point in Elk Grove with Community Relations Director Jaime Cervantes.": "Reserve una visita en persona o por video a Bruceville Point en Elk Grove con Jaime Cervantes, Director de Relaciones con la Comunidad.",
  "Tours by appointment": "Visitas con cita previa",
  "Stay for lunch": "Quédese a almorzar",
  "Choose a time that suits you, in person or by video. Jaime will show you the apartments and the spaces, introduce you to a few residents, and answer every question.": "Elija el horario que mejor le convenga, en persona o por video. Jaime le mostrará los departamentos y los espacios, le presentará a algunos residentes y responderá todas sus preguntas.",
  "A live walk-through with Jaime from wherever you are.": "Un recorrido en vivo con Jaime desde donde usted esté.",
  "Stay for lunch.": "Quédese a almorzar.",
  "Join us in Stone Lakes Cafe or the Cypress Room after your tour.": "Acompáñenos en Stone Lakes Cafe o en The Cypress Room después de su visita.",
  "The daily specials from the Cypress Room and Stone Lakes Cafe.": "Las especialidades del día de The Cypress Room y Stone Lakes Cafe.",
  "— live or online — are arranged for residents and visitors who are deaf or hard of hearing, when appropriate. Let us know when you book.": "(en persona o en línea) se coordinan para residentes y visitantes sordos o con dificultades auditivas, cuando corresponda. Avísenos al reservar.",
  "Reasonable accommodations": "Adaptaciones razonables",
  "for people with disabilities, including hearing impairment. Just ask the front desk team.": "para personas con discapacidad, incluida la discapacidad auditiva. Solo pídalas al equipo de recepción.",
  "Bruceville Point is operated by": "Bruceville Point es operado por",
  "Bruceville Point’s accessibility statement: our WCAG 2.1 AA goal, text size, contrast and language tools, ASL interpreters and reasonable accommodations.": "Declaración de accesibilidad de Bruceville Point: nuestra meta WCAG 2.1 AA, herramientas de tamaño de texto, contraste e idioma, intérpretes de ASL y adaptaciones razonables.",
  "Bruceville Point is a home for everyone, and our website, printed materials and community spaces should be too.": "Bruceville Point es un hogar para todos, y nuestro sitio web, materiales impresos y espacios comunitarios también deben serlo.",
  "If you opt in to text messages, Bruceville Point will send you recurring automated texts about the topics you chose — such as your tour, the weekly activity calendar, daily menus, photos and news, Harbor updates or urgent notices.": "Si acepta recibir mensajes de texto, Bruceville Point le enviará mensajes automáticos y recurrentes sobre los temas que eligió, como su visita, el calendario semanal de actividades, los menús del día, fotos y noticias, novedades de Harbor o avisos urgentes.",
  "How Bruceville Point and Tenfold Senior Living collect, use and protect your information, our cookie policy and SMS terms.": "Cómo Bruceville Point y Tenfold Senior Living recopilan, usan y protegen su información, nuestra política de cookies y los términos de mensajes de texto.",
  "Bruceville Point is operated by Tenfold Senior Living. This policy explains what we collect when you use our website, how we use it and the choices you have.": "Bruceville Point es operado por Tenfold Senior Living. Esta política explica qué información recopilamos cuando usa nuestro sitio web, cómo la usamos y las opciones que usted tiene.",
  "Dimensions are approximate. Layouts vary slightly from apartment to apartment, so Jaime can show you the exact homes that are open.": "Las medidas son aproximadas. La distribución varía un poco de un departamento a otro, así que Jaime puede mostrarle exactamente los departamentos que están disponibles.",
  "Open now and ready to reserve. Join the alert list and we’ll tell you if another A1 opens up.": "Disponible ahora y listo para reservar. Únase a la lista de alertas y le avisaremos si se desocupa otro A1.",
