  ". Most care services are included, and additional care level rates are set by a personal assessment with Amrita Sapkota, our Harbor Director.": ". La mayoría de los servicios de cuidado están incluidos, y las tarifas de los niveles de cuidado adicionales se fijan mediante una evaluación personal con Amrita Sapkota, nuestra Directora de Harbor.",
