  "Your apartment, your schedule, your choices. Cook in your own kitchen or dine in one of our restaurants, join an outing or enjoy a quiet afternoon, and come and go as you please.": "Su departamento, su horario, sus decisiones. Cocine en su propia cocina o coma en uno de nuestros restaurantes, únase a una salida o disfrute de una tarde tranquila, y entre y salga cuando guste.",
  "No second-person fee for couples, Assisted Living Services if and when you want them, and a team that listens before it acts. That’s what we mean by Different By Design.": "Sin cargo por segunda persona para parejas, Servicios de Vida Asistida si los quiere y cuando los quiera, y un equipo que escucha antes de actuar. Eso es lo que queremos decir con “Diferentes por diseño”.",
