  "Luxury senior living in Folsom and Elk Grove, California: spacious apartments, Assisted Living Services in every apartment, Harbor Memory Care and a lifestyle that keeps you youthful, useful, spontaneous and mobile.": "Comunidades de lujo para personas mayores en Folsom y Elk Grove, California: departamentos amplios, Servicios de Vida Asistida en cada departamento, Harbor (cuidado de la memoria) y un estilo de vida que le mantiene juvenil, útil, espontáneo y activo.",
