  "Two open communities in Sacramento County, each with Independent Living, Assisted Living Services and Harbor Memory Care.": "Dos comunidades abiertas en el condado de Sacramento, cada una con Vida Independiente, Servicios de Vida Asistida y Harbor (cuidado de la memoria).",
  "Real apartment homes, not rooms. Bring the dining table, the sectional and the art you love.": "Verdaderos departamentos, no cuartos. Traiga la mesa del comedor, el sofá seccional y el arte que ama.",
  "Harbor is a home-like, secured neighborhood within each community, with its own courtyard, its own activity team and its own Events & Adventures calendar.": "Harbor es un área hogareña y segura dentro de cada comunidad, con su propio patio, su propio equipo de actividades y su propio calendario de Eventos y Aventuras.",
