  "YUSM is the philosophy behind every Tenfold calendar, menu and class. It’s how we help residents keep living fully.": "YUSM es la filosofía detrás de cada calendario, menú y clase de Tenfold. Es nuestra manera de ayudar a los residentes a seguir viviendo plenamente.",
