  "Different By Design": "Diferentes por diseño",
  "Tenfold apartments are designed like the home you have now: full-sized kitchens, room for your furniture and big windows. Outside your door are restaurants, a fitness program and a calendar full of Events & Adventures.": "Los departamentos Tenfold están diseñados como el hogar que tiene ahora: cocinas completas, espacio para sus muebles y ventanales. Al salir de su puerta encontrará restaurantes, un programa de acondicionamiento físico y un calendario lleno de Eventos y Aventuras.",
