  "Harbor Memory Care: communities side by side": "Harbor (cuidado de la memoria): comunidades lado a lado",
  "Harbor Memory Care at Tenfold communities in Folsom and Elk Grove: a home-like, secured neighborhood with its own courtyard, activity team and Events & Adventures.": "Harbor (cuidado de la memoria) en las comunidades Tenfold de Folsom y Elk Grove: un área hogareña y segura con su propio patio, equipo de actividades y Eventos y Aventuras.",
  "Life at Harbor": "La vida en Harbor",
  "Harbor residents have their own activity team and their own Events & Adventures, with outings beyond the community, and they are welcome at every community event.": "Los residentes de Harbor tienen su propio equipo de actividades y sus propios Eventos y Aventuras, con salidas fuera de la comunidad, y son bienvenidos en todos los eventos de la comunidad.",
  "Not just a home,": "No solo un hogar,",
  "a lifestyle": "un estilo de vida",
  "Every Tenfold calendar, menu and class is built on one idea: that the years ahead should be youthful, useful, spontaneous and mobile.": "Cada calendario, menú y clase de Tenfold se basa en una idea: que los años por venir sean juveniles, útiles, espontáneos y activos.",
  "Four words we": "Cuatro palabras",
